<template>
    <AdminLayout>
        <main class="mx-auto max-w-7xl space-y-6" :aria-labelledby="titleId">
            <AdminPageHeader :eyebrow="eyebrow" :title="title" :description="description" :title-id="titleId">
                <template #action><button type="button" class="primary-action" :disabled="loading || processing" @click="openModal()"><i class="pi pi-plus mr-2" aria-hidden="true"></i>Nueva {{ singular }}</button></template>
            </AdminPageHeader>
            <section class="grid gap-3 sm:grid-cols-2" :aria-label="`Resumen de ${title}`">
                <article class="metric"><span>Total de {{ title.toLowerCase() }}</span><strong>{{ total }}</strong><small>Resultado global del listado</small></article>
                <article class="metric"><span>Productos relacionados</span><strong>{{ relatedTotal }}</strong><small>Suma de esta página</small></article>
            </section>
            <form class="filter-panel" :aria-label="`Filtros de ${title}`" @submit.prevent="load(1)">
                <div class="grid gap-3 sm:grid-cols-[minmax(0,1fr)_auto]"><label class="label">Buscar <div class="relative mt-1"><i class="pi pi-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" aria-hidden="true"></i><input v-model.trim="search" class="field pl-10" :placeholder="`Buscar ${singular.toLowerCase()} por nombre`" autocomplete="off"></div></label>
                    <div class="flex flex-wrap items-end gap-2"><button class="primary-action" :disabled="loading" type="submit"><i class="pi pi-filter mr-2" aria-hidden="true"></i>Aplicar</button><button class="secondary-action" :disabled="loading" type="button" @click="clear"><i class="pi pi-times mr-2" aria-hidden="true"></i>Limpiar</button><button class="icon-control" :disabled="loading" type="button" aria-label="Actualizar listado" data-tooltip="Actualizar" @click="load(page)"><i class="pi pi-refresh" :class="{ 'pi-spin': loading }" aria-hidden="true"></i></button></div>
                </div>
            </form>
            <section v-if="loadError" class="rounded-2xl border border-red-200 bg-red-50 p-5 text-red-900" role="alert"><p class="font-bold"><i class="pi pi-exclamation-circle mr-2" aria-hidden="true"></i>No se pudo cargar el listado</p><p class="mt-1 text-sm">{{ loadError }}</p><button type="button" class="mt-3 secondary-action" @click="load(page)">Reintentar</button></section>
            <section v-else class="overflow-hidden rounded-2xl bg-white shadow-sm">
                <div class="overflow-x-auto"><table class="w-full min-w-[660px] text-left text-sm"><thead class="bg-slate-100 text-xs font-bold uppercase tracking-wide text-slate-600"><tr><th scope="col" class="p-4">{{ singular }}</th><th scope="col" class="p-4 text-center">Productos</th><th scope="col" class="p-4 text-center">Estado</th><th scope="col" class="p-4 text-right">Acciones</th></tr></thead>
                    <tbody>
                        <template v-if="loading"><tr v-for="row in 5" :key="row" class="border-t"><td v-for="cell in 4" :key="cell" class="p-4"><div class="h-5 animate-pulse rounded bg-slate-200" :class="cell === 1 ? 'w-48' : 'mx-auto w-20'"></div></td></tr></template>
                        <template v-else-if="items.length"><tr v-for="item in items" :key="item.id" class="border-t border-slate-100 transition hover:bg-slate-50"><td class="p-4"><div class="flex items-center gap-3"><img v-if="imageEnabled && item.image_url && !failedImages.has(item.id)" :src="item.image_url" :alt="`Imagen de ${item.name}`" class="h-12 w-16 rounded-lg border border-slate-200 bg-slate-50 object-cover" loading="lazy" @error="failedImages.add(item.id)"><span v-else class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-blue-50 font-black text-blue-700"><i :class="icon" aria-hidden="true"></i></span><span class="font-semibold text-slate-900">{{ item.name }}</span></div></td><td class="p-4 text-center font-semibold text-slate-700">{{ safeNumber(item.products_count) }}</td><td class="p-4 text-center"><AdminStatusBadge :active="isActive(item)" :active-label="'Activa'" :inactive-label="'Inactiva'" /></td><td class="p-4"><div class="flex justify-end gap-1"><AdminIconButton icon="pi pi-pencil" label="Editar" @click="openModal(item)" /><AdminIconButton :icon="isActive(item) ? 'pi pi-ban' : 'pi pi-check-circle'" :label="isActive(item) ? 'Desactivar' : 'Activar'" :tone="isActive(item) ? 'text-red-700' : 'text-emerald-700'" @click="confirmStatus(item)" /></div></td></tr></template>
                        <tr v-else><td colspan="4"><AdminEmptyState :icon="search ? 'pi pi-search' : icon" :title="search ? `No encontramos ${title.toLowerCase()} con esa búsqueda` : `Todavía no hay ${title.toLowerCase()}`" :description="search ? 'Prueba ajustando o limpiando la búsqueda.' : `Crea la primera ${singular.toLowerCase()} desde este panel.`"><button type="button" class="mt-4 primary-action" @click="search ? clear() : openModal()">{{ search ? 'Limpiar búsqueda' : `Nueva ${singular}` }}</button></AdminEmptyState></td></tr>
                    </tbody>
                </table></div><AdminPagination :page="page" :last-page="lastPage" :loading="loading" :summary="paginationSummary" @change="load" />
            </section>
            <div v-if="showModal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" :aria-labelledby="modalTitle">
                <form class="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-2xl" @submit.prevent="save">
                    <header class="flex items-start gap-3 border-b border-slate-100 p-5"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-800"><i :class="editing ? 'pi pi-pencil' : 'pi pi-plus'" aria-hidden="true"></i></span><div class="flex-1"><h2 :id="modalTitle" class="text-xl font-black text-slate-900">{{ editing ? `Editar ${singular}` : `Nueva ${singular}` }}</h2><p class="mt-1 text-sm text-slate-600">{{ editing ? 'Actualiza el nombre sin cambiar sus relaciones.' : `Registra una nueva ${singular.toLowerCase()} para el catálogo.` }}</p></div><AdminIconButton icon="pi pi-times" label="Cerrar" :disabled="processing || imageProcessing" @click="closeModal" /></header>
                    <div class="space-y-5 p-5"><div><label class="label">Nombre<input v-model.trim="form.name" class="field mt-1" autofocus required></label><p v-if="errors.name" class="mt-1 text-xs font-semibold text-red-700">{{ errors.name[0] }}</p></div>
                        <section v-if="imageEnabled" class="space-y-3" aria-labelledby="category-image-label"><div><h3 id="category-image-label" class="text-sm font-bold text-slate-800">Imagen de categoría</h3><p class="mt-1 text-sm text-slate-600">JPEG, PNG o WebP. Máximo 2 MB; mínimo 640 × 400 px.</p></div>
                            <div class="grid gap-4 sm:grid-cols-2"><div class="aspect-[16/10] overflow-hidden rounded-xl border border-slate-200 bg-gradient-to-br from-blue-50 to-slate-100"><img v-if="previewUrl" :src="previewUrl" :alt="`Vista previa de ${form.name || singular}`" class="h-full w-full object-cover"><img v-else-if="form.image_url && !modalImageFailed" :src="form.image_url" :alt="`Imagen actual de ${form.name}`" class="h-full w-full object-cover" @error="modalImageFailed = true"><div v-else class="flex h-full flex-col items-center justify-center gap-2 text-blue-800"><i class="pi pi-tag text-3xl" aria-hidden="true"></i><span class="max-w-[85%] text-center text-sm font-semibold">{{ form.name || 'Vista previa de categoría' }}</span></div></div>
                                <div class="flex flex-col justify-center gap-3"><p class="text-sm text-slate-600" aria-live="polite">{{ selectedFile?.name || (form.id && form.image_url ? 'Imagen actual guardada' : 'Sin imagen seleccionada') }}</p><label class="secondary-action flex min-h-11 cursor-pointer items-center justify-center gap-2 text-center"><i class="pi pi-upload" aria-hidden="true"></i>{{ selectedFile ? 'Cambiar selección' : 'Seleccionar imagen' }}<input class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" :disabled="processing || imageProcessing" @change="selectImage"></label><button v-if="selectedFile" type="button" class="min-h-11 text-sm font-semibold text-slate-600 underline" :disabled="processing" @click="clearSelectedImage">Retirar selección</button><Button v-if="editing && form.image_url && !selectedFile" type="button" severity="danger" outlined size="small" label="Eliminar imagen" icon="pi pi-trash" :disabled="processing || imageProcessing" @click="confirmRemoveImage" /></div></div>
                            <p v-if="imageError || errors.image" class="text-sm font-semibold text-red-700" role="alert">{{ imageError || 'La imagen no cumple los requisitos de formato, tamaño o dimensiones.' }}</p><p class="text-xs text-slate-500">La imagen existente se conserva si guardas sin elegir otra.</p>
                        </section>
                    </div>
                    <footer class="flex justify-end gap-3 border-t border-slate-100 p-5"><button type="button" class="secondary-action" :disabled="processing || imageProcessing" @click="closeModal">Cancelar</button><button class="primary-action" :disabled="processing || imageProcessing">{{ processing ? 'Guardando…' : 'Guardar' }}</button></footer>
                </form>
            </div>
        </main>
    </AdminLayout>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useConfirm } from 'primevue/useconfirm';
import { useToast } from 'primevue/usetoast';
import Button from 'primevue/button';
import AdminLayout from '@/layouts/AdminLayout.vue';
import AdminEmptyState from '@/components/admin/AdminEmptyState.vue';
import AdminIconButton from '@/components/admin/AdminIconButton.vue';
import AdminPageHeader from '@/components/admin/AdminPageHeader.vue';
import AdminPagination from '@/components/admin/AdminPagination.vue';
import AdminStatusBadge from '@/components/admin/AdminStatusBadge.vue';
import api from '@/api';

const props = defineProps({ endpoint: { type: String, required: true }, title: { type: String, required: true }, singular: { type: String, required: true }, eyebrow: { type: String, required: true }, description: { type: String, required: true }, icon: { type: String, default: 'pi pi-tag' }, imageEnabled: { type: Boolean, default: false } });
const toast = useToast();
const confirm = useConfirm();
const items = ref([]); const search = ref(''); const page = ref(1); const lastPage = ref(1); const total = ref(0); const loading = ref(false); const loadError = ref(''); const showModal = ref(false); const editing = ref(false); const processing = ref(false); const imageProcessing = ref(false); const form = ref({ id: null, name: '', image_url: null }); const errors = ref({}); const selectedFile = ref(null); const previewUrl = ref(''); const imageError = ref(''); const failedImages = ref(new Set()); const modalImageFailed = ref(false);
const titleId = computed(() => `${props.singular.toLowerCase()}-title`); const modalTitle = computed(() => `${props.singular.toLowerCase()}-modal-title`); const relatedTotal = computed(() => items.value.reduce((sum, item) => sum + (Number(item.products_count) || 0), 0)); const paginationSummary = computed(() => total.value ? `${items.value.length} de ${total.value} registros` : 'Sin registros para mostrar');
const validId = id => Number.isInteger(Number(id)) && Number(id) > 0; const safeNumber = value => Math.max(0, Number(value) || 0); const isActive = item => item.is_active !== false && Number(item.is_active) !== 0;

async function load(target = 1) { if (loading.value) return; loading.value = true; loadError.value = ''; try { const { data } = await api.get(props.endpoint, { params: { page: target, search: search.value || undefined } }); items.value = data.data || []; page.value = Number(data.current_page) || 1; lastPage.value = Number(data.last_page) || 1; total.value = safeNumber(data.total); } catch { loadError.value = 'No se pudo cargar la información.'; } finally { loading.value = false; } }
function clear() { search.value = ''; load(1); }
function releasePreview() { if (previewUrl.value) { URL.revokeObjectURL(previewUrl.value); previewUrl.value = ''; } }
function resetImageSelection() { releasePreview(); selectedFile.value = null; imageError.value = ''; }
function closeModal() { if (processing.value || imageProcessing.value) return; showModal.value = false; editing.value = false; resetImageSelection(); form.value = { id: null, name: '', image_url: null }; errors.value = {}; modalImageFailed.value = false; }
function openModal(item = null) { if (item && !validId(item.id)) { toast.add({ severity: 'error', summary: 'Registro inválido', detail: 'No se puede editar este registro.', life: 3000 }); return; } resetImageSelection(); editing.value = !!item; form.value = { id: item?.id || null, name: item?.name || '', image_url: item?.image_url || null }; modalImageFailed.value = false; errors.value = {}; showModal.value = true; }
async function selectImage(event) { const file = event.target.files?.[0]; event.target.value = ''; imageError.value = ''; if (!file) return; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 2 * 1024 * 1024) { imageError.value = 'Elige una imagen JPEG, PNG o WebP de hasta 2 MB.'; return; } const url = URL.createObjectURL(file); try { const dimensions = await new Promise((resolve, reject) => { const image = new Image(); image.onload = () => resolve({ width: image.naturalWidth, height: image.naturalHeight }); image.onerror = reject; image.src = url; }); if (dimensions.width < 640 || dimensions.height < 400 || dimensions.width > 4000 || dimensions.height > 2500 || dimensions.width * dimensions.height > 10_000_000) { URL.revokeObjectURL(url); imageError.value = 'La imagen debe medir entre 640 × 400 y 4000 × 2500 px.'; return; } releasePreview(); selectedFile.value = file; previewUrl.value = url; } catch { URL.revokeObjectURL(url); imageError.value = 'No se pudo leer la imagen seleccionada.'; } }
function clearSelectedImage() { resetImageSelection(); }
async function save() { if (processing.value || imageProcessing.value) return; processing.value = true; errors.value = {}; try { let response; if (props.imageEnabled && selectedFile.value) { const data = new FormData(); data.append('name', form.value.name); data.append('image', selectedFile.value); if (editing.value) data.append('_method', 'PUT'); response = await api.post(editing.value ? `${props.endpoint}/${form.value.id}` : props.endpoint, data); } else { response = editing.value ? await api.put(`${props.endpoint}/${form.value.id}`, { name: form.value.name }) : await api.post(props.endpoint, { name: form.value.name }); } if (props.imageEnabled && response?.data?.image_url === undefined) { imageError.value = 'No se pudo confirmar la imagen guardada.'; return; } showModal.value = false; editing.value = false; resetImageSelection(); form.value = { id: null, name: '', image_url: null }; toast.add({ severity: 'success', summary: 'Guardado', detail: `${props.singular} guardada correctamente.`, life: 2500 }); await load(page.value); } catch (error) { errors.value = error.response?.status === 422 ? error.response.data.errors || {} : {}; if (props.imageEnabled && errors.value.image) imageError.value = 'La imagen no cumple los requisitos de formato, tamaño o dimensiones.'; toast.add({ severity: 'error', summary: 'No se pudo guardar', detail: props.imageEnabled ? 'Revisa el nombre y los requisitos de la imagen.' : 'No se pudo guardar la información.', life: 3500 }); } finally { processing.value = false; } }
function confirmRemoveImage() { if (!validId(form.value.id) || !form.value.image_url || imageProcessing.value) return; confirm.require({ message: '¿Eliminar la imagen de esta categoría? La categoría y sus productos se conservarán.', header: 'Eliminar imagen', icon: 'pi pi-exclamation-triangle', acceptLabel: 'Eliminar imagen', rejectLabel: 'Cancelar', accept: removeImage }); }
async function removeImage() { if (imageProcessing.value || !validId(form.value.id)) return; imageProcessing.value = true; try { const { data } = await api.delete(`${props.endpoint}/${form.value.id}/image`); form.value.image_url = data.image_url || null; items.value = items.value.map(item => item.id === form.value.id ? { ...item, image_url: data.image_url || null } : item); toast.add({ severity: 'success', summary: 'Imagen eliminada', detail: 'La categoría se conservó sin imagen.', life: 2500 }); } catch { toast.add({ severity: 'error', summary: 'No se pudo eliminar', detail: 'Inténtalo nuevamente.', life: 3500 }); } finally { imageProcessing.value = false; } }
function confirmStatus(item) { if (!validId(item?.id)) return; const next = !isActive(item); confirm.require({ message: `¿Desea ${next ? 'activar' : 'desactivar'} ${item.name}?`, header: 'Confirmar cambio de estado', icon: 'pi pi-exclamation-triangle', acceptLabel: 'Confirmar', rejectLabel: 'Cancelar', accept: () => changeStatus(item, next) }); }
async function changeStatus(item, next) { try { await api.patch(`${props.endpoint}/${item.id}/status`, { is_active: next }); toast.add({ severity: 'success', summary: 'Estado actualizado', detail: `${props.singular} ${next ? 'activada' : 'desactivada'}.`, life: 2500 }); await load(page.value); } catch { toast.add({ severity: 'error', summary: 'No se pudo cambiar el estado', detail: 'Inténtalo nuevamente.', life: 4000 }); } }
onMounted(() => load());
onBeforeUnmount(resetImageSelection);
</script>

<style scoped>
.metric{border:1px solid #e2e8f0;border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 1px 2px #0f172a0d}.metric span,.metric small{display:block;color:#64748b;font-size:.8rem;font-weight:600}.metric strong{display:block;margin:.35rem 0;font-size:1.65rem;color:#0f172a}.filter-panel{border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 1px 2px #0f172a0d}.label{display:block;font-size:.875rem;font-weight:700;color:#334155}.field{width:100%;border:1px solid #cbd5e1;border-radius:.65rem;padding:.65rem .8rem;color:#0f172a}.field:focus{outline:2px solid #3b82f6;outline-offset:1px}.primary-action,.secondary-action,.icon-control{min-height:2.5rem;border-radius:.6rem;font-weight:700}.primary-action{background:#2563eb;padding:.55rem .85rem;color:#fff}.secondary-action{border:1px solid #cbd5e1;padding:.55rem .85rem;color:#334155}.icon-control{position:relative;width:2.5rem;border:1px solid #cbd5e1;color:#334155}button:disabled{cursor:not-allowed;opacity:.55}button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.icon-control::after{content:attr(data-tooltip);position:absolute;z-index:60;bottom:calc(100% + .4rem);left:50%;transform:translateX(-50%);visibility:hidden;border-radius:.35rem;background:#0f172a;padding:.3rem .5rem;color:#fff;font-size:.75rem;opacity:0}.icon-control:hover::after,.icon-control:focus-visible::after{visibility:visible;opacity:1}
</style>
